}
if (mensajeUsuario === "(no capturado)" && mock.mensajeUsuario) {
  mensajeUsuario = mock.mensajeUsuario;
}

// ═══════════════════════════════════════════
// CONSTRUIR MENSAJE
// ═══════════════════════════════════════════

const problemas = guardia.problemas;
const severidad = guardia.severidad || "WARNING";
const timestamp = guardia.timestamp || new Date().toISOString();
const outputOriginal = guardia.outputOriginal || "(vacío)";
const outputUsuario = $json.output || "(sin output)";

const iconoSeveridad = severidad === "CRITICO" ? "🚨" : "⚠️";
const mockTag = isMock ? "\n🧪 *MODO TEST — DATOS SIMULADOS*" : "";

const mensaje =
`${iconoSeveridad} *ALERTA NILAH — ${severidad}*${mockTag}
━━━━━━━━━━━━━━━━━━━━

*Problemas detectados:*
${problemas.join('\n')}

🏪 *Negocio:* ${businessName}
🆔 *ID:* \`${businessId}\`
👤 *Cliente:* \`${telefonoCliente}\`
🕐 *Hora:* ${timestamp}
🔗 *Ejecución:* \`${$execution.id}\`

💬 *Cliente escribió:*
"${mensajeUsuario}"

🤖 *Output original del agente:*
"${outputOriginal}"

✉️ *Respuesta enviada al cliente:*
"${outputUsuario}"

━━━━━━━━━━━━━━━━━━━━`;

return [{ json: { mensaje } }];

// =============================================
// CALCULAR DELAY HUMANO (Anti-Ban)
// =============================================

const output = $input.first().json.output || "";
const longitud = output.length;
const esAudio = $input.first().json.has_media && $input.first().json.media_type.includes("audio");

// Configuración Base
const BASE_DELAY = 1000; // 1.5 segundos mínimo para pensar
const MS_POR_CARACTER = 30; // 30ms por letra (aprox 300-400 chars por minuto)
const MAX_DELAY = 12000; // Tope máximo de 12 segundos para no aburrir

// Cálculo
let delayCalculado = BASE_DELAY + (longitud * MS_POR_CARACTER);

// Ajuste si es audio (tarda más en "grabar")
if (esAudio) {
  delayCalculado += 2000; 
}

// Jitter (variación aleatoria ±10%) para naturalidad
const jitter = Math.floor(Math.random() * (delayCalculado * 0.2)) - (delayCalculado * 0.1);
let delayFinal = Math.floor(delayCalculado + jitter);

// Aplicar límites
if (delayFinal > MAX_DELAY) delayFinal = MAX_DELAY;
if (delayFinal < 1000) delayFinal = 1000;

// Convertir a segundos para el nodo Wait (si usa segundos) o mantener ms
const delaySeconds = Math.ceil(delayFinal / 1000);

return {
  json: {
    ...$input.first().json,
    delay_ms: delayFinal,
    delay_seconds: delaySeconds,
    _debug_delay: `Longitud: ${longitud} | Delay: ${delaySeconds}s`
  }
};

