// Obtenemos el texto base
let fullText = items[0].json.texto || items[0].json.output || items[0].json.text || "";

// 1. NORMALIZACIÓN: Bajamos todo a asterisco simple (*) primero para no confundirnos
fullText = fullText
    .replace(/\*\*/g, '*')  // Si viene doble, lo volvemos simple
    .replace(/\\\*/g, '*'); // Si viene escapado, lo limpiamos

// 2. EL CIRUJANO DE NEGRITAS (La corrección clave)
// Busca texto entre dos asteriscos, le quita los espacios internos y lo convierte a doble (**) para Chatwoot
// Esto RESPETA los espacios de afuera, solucionando tu problema actual.
fullText = fullText.replace(/\*([^*]+)\*/g, (match, contenido) => {
    return '**' + contenido.trim() + '**';
});

// 3. LOGICA DE CORTE (Smart Splitter)
const MAX_LENGTH = 400;
let part1 = "";
let part2 = "";
let needsSplit = false;

if (fullText.length <= MAX_LENGTH) {
    part1 = fullText;
    part2 = "";
    needsSplit = false;
} else {
    // Buscamos la mitad
    const middle = Math.floor(fullText.length / 2);

    // Prioridad de corte: Salto de línea -> Punto -> Espacio -> A la fuerza
    let splitIndex = fullText.lastIndexOf('\n', middle + 200); 
    if (splitIndex === -1 || splitIndex < middle - 200) splitIndex = fullText.lastIndexOf('. ', middle + 200);
    if (splitIndex === -1) splitIndex = fullText.lastIndexOf(' ', middle + 200);
    if (splitIndex === -1) splitIndex = middle;

    part1 = fullText.substring(0, splitIndex + 1).trim();
    part2 = fullText.substring(splitIndex + 1).trim();
    needsSplit = true;

    // REPARACIÓN DE CORTE: 
    // Si cortamos justo en medio de una negrita (contando los **), cerramos en uno y abrimos en otro
    const countOccurrences = (str, sub) => (str.split(sub).length - 1);

    // Si quedó un número impar de dobles asteriscos (**), cerramos la etiqueta
    if (countOccurrences(part1, '**') % 2 !== 0) {
        part1 += '**';    // Cerramos en la parte 1
        part2 = '**' + part2; // Reabrimos en la parte 2
    }
}

return [{
  json: {
    part1: part1,
    part2: part2,
    needs_split: needsSplit
  }
}];

