    chatbot_tipo: configTenant.chatbot_tipo || 'autonomo',
    recursos_saas: configTenant.recursos_saas || {}
  }
}];

// =============================================
// RECUPERAR DATOS WEBHOOK - Multi-Tenant
// Lee datos del tenant config + webhook original
// =============================================

// 1. RECUPERAR DATOS DEL TENANT CONFIG
const tenantConfig = $('Combinar Config Tenant').first().json;

// 3. LÓGICA DE ESTADO (Bot On/Off)
let isBotOn = tenantConfig.bot_active;

// 4. SALIDA FINAL
return {
  json: {
    bot_active: isBotOn,
    // Datos del mensaje (ya normalizados)
    message_content: tenantConfig.content,
    conversation_id: tenantConfig.conversation_id,
    contact_id: tenantConfig.contact_id,
    sender_name: tenantConfig.sender_name,
    attachments: tenantConfig.attachments || [],


    // === DATOS DEL TENANT (propagados) ===
    business_id: tenantConfig.business_id,
    nombre_negocio: tenantConfig.nombre_negocio,
    nombre_bot: tenantConfig.nombre_bot,
    timezone: tenantConfig.timezone,
    moneda: tenantConfig.moneda,
    idioma: tenantConfig.idioma,
    chatwoot_api_url: tenantConfig.chatwoot_api_url,
    chatwoot_api_token: tenantConfig.chatwoot_api_token,
    chatwoot_account_id: tenantConfig.chatwoot_account_id,
    sender_phone: (tenantConfig.sender_phone || '').replace('+', ''),
    inbox_id: tenantConfig.inbox_id,
    canal: tenantConfig.canal, 
    telefono_recepcionista: tenantConfig.telefono_recepcionista,
    marca_identidad: tenantConfig.marca_identidad,
     // --- NUEVO: Estado del bot por cliente ---
    bot_cliente_pausado: tenantConfig.bot_cliente_pausado,
    bot_pausado_hasta: tenantConfig.bot_pausado_hasta,
    bot_pausado_razon: tenantConfig.bot_pausado_razon
  }
};

// === Inyectar Contexto Dia ===
// Agrega la fecha actual, dia de la semana, manana, etc.
// Tambien propaga chatbot_tipo para el switch de enrutamiento.

const item = $input.first().json;

const tz = item.timezone || 'America/Lima';
const now = new Date();

// Funciones de fecha
function formatDateForTZ(date) {
  const opts = { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' };
  const parts = new Intl.DateTimeFormat('en-CA', opts).formatToParts(date);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const d = parts.find(p => p.type === 'day').value;
  return `${y}-${m}-${d}`;
}

function getDayName(date) {
  return date.toLocaleDateString('es-PE', { weekday: 'long', timeZone: tz });
}

function getFullDateStr(date) {
  return date.toLocaleDateString('es-PE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: tz });
}

function getHora(date) {
  return date.toLocaleTimeString('es-PE', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: tz });
}

const hoyISO = formatDateForTZ(now);
const manana = new Date(now.getTime() + 86400000);
const pasado = new Date(now.getTime() + 2 * 86400000);

// Datos de cierre (propagados desde nodo anterior)
const ctxDia = item.contexto_dia || {};

return [{
  json: {
    ...item,
    contexto_dia: ctxDia,
    HOY: getFullDateStr(now),
    HORA_ACTUAL: getHora(now),
    HOY_ISO: hoyISO,
    MAÑANA: getFullDateStr(manana),
    MAÑANA_ISO: formatDateForTZ(manana),
    PASADO_MAÑANA: getFullDateStr(pasado),
    PASADO_ISO: formatDateForTZ(pasado),
    DIA_SEMANA_HOY: getDayName(now),
    DIA_SEMANA_MAÑANA: getDayName(manana),
    cerrado: ctxDia.cerrado || false,
    cierre_parcial: ctxDia.cierre_parcial || false,
    motivo_cierre: ctxDia.motivo || null,
    hora_inicio_cierre: ctxDia.hora_inicio_cierre || null,
    hora_fin_cierre: ctxDia.hora_fin_cierre || null,
    hora_reapertura: ctxDia.hora_reapertura || null,
    mensaje_cierre: ctxDia.mensaje_cierre || null,
    MEDIA_URL: ctxDia.MEDIA_URL || item.MEDIA_URL || null,
  }
}];

// =============================================
// 🚧 PROCESAR RESULTADO DE CIERRE
// (Soporte para día completo y cierre parcial + Multi-Tenant)
// =============================================

const resultado = $input.first().json;
const tenantTimezone = $('recuperar datos webhook').first().json.timezone || 'America/Lima';
const ahoraMismo = DateTime.now().setZone(tenantTimezone);
const horaActual = ahoraMismo.toFormat('HH:mm');

// Si no hay registro, el día está ABIERTO
if (!resultado || !resultado.fecha) {
    return {
        json: {
            cerrado: false,
            cierre_parcial: false,
            es_dia_completo: false,
            motivo: null,
            mensaje_cierre: null,
            hora_inicio_cierre: null,
            hora_fin_cierre: null,
            hora_reapertura: null,
            actualmente_cerrado: false
        }
    };
}

// Hay un registro de cierre para hoy
const esDiaCompleto = resultado.es_dia_completo !== false; // Default true

if (esDiaCompleto) {
    // 🔴 DÍA COMPLETO CERRADO
    return {
        json: {
            cerrado: true,
            cierre_parcial: false,
            es_dia_completo: true,
            motivo: resultado.motivo || 'Cerrado',
            hora_inicio_cierre: null,
            hora_fin_cierre: null,
            hora_reapertura: null,
            mensaje_cierre: resultado.mensaje_chatbot || `Hoy estamos cerrados por ${resultado.motivo || 'mantenimiento'}.`,
            actualmente_cerrado: true
        }
    };
} else {
    // 🟡 CIERRE PARCIAL
    const horaInicio = resultado.hora_inicio || '09:00';
    const horaFin = resultado.hora_fin || '13:00';

    // Normalizar horas a formato HH:mm para comparación segura
    const horaActualNorm = horaActual.padStart(5, '0');
    const horaInicioNorm = horaInicio.padStart(5, '0');
    const horaFinNorm = horaFin.padStart(5, '0');

    // Verificar si AHORA estamos en el rango cerrado
    const dentroDelCierreParcial = horaActualNorm >= horaInicioNorm && horaActualNorm < horaFinNorm;

    // Formatear hora de reapertura para mostrar (ej: "1:00 PM")
    const [h, m] = horaFin.split(':');
    const horaReaperturaFormateada = parseInt(h) > 12 
        ? `${parseInt(h) - 12}:${m} PM` 
        : parseInt(h) === 12 
            ? `12:${m} PM`
            : `${parseInt(h)}:${m} AM`;

    return {
        json: {
            cerrado: dentroDelCierreParcial,
            cierre_parcial: true,
            es_dia_completo: false,
            motivo: resultado.motivo || 'Cierre parcial',
            hora_inicio_cierre: horaInicio,
            hora_fin_cierre: horaFin,
            hora_reapertura: horaFin,
            hora_reapertura_formateada: horaReaperturaFormateada,
            mensaje_cierre: resultado.mensaje_chatbot || `Hoy estamos cerrados de ${horaInicio} a ${horaFin} por ${resultado.motivo || 'mantenimiento'}.`,
            actualmente_cerrado: dentroDelCierreParcial
        }
    };
}

const output = $input.first().json.output || $('Guardia de Respuesta').first().json.output || "";
const guardia = $input.first().json._guardia || {};
const paso = $input.first().json._paso || "ok";

// Detectar URLs de imagen
const imagenRegex = /(https?:\/\/[^\s]+\.(jpg|jpeg|png|webp|gif))/gi;
// Detectar URLs de video (mp4, mov, Google Drive)
const videoRegex = /(https?:\/\/[^\s]+\.(mp4|mov|avi|webm))|(https?:\/\/drive\.google\.com\/[^\s]+)/gi;

const imagenes = (output || "").match(imagenRegex) || [];
const videos = (output || "").match(videoRegex) || [];

// Limpiar texto (quitar todas las URLs de media)
let textoLimpio = output || "";
imagenes.forEach(url => textoLimpio = textoLimpio.replace(url, ''));
videos.forEach(url => textoLimpio = textoLimpio.replace(url, ''));
textoLimpio = textoLimpio.replace(/\n{3,}/g, '\n\n').trim();

// Determinar tipo de media
let tipoMedia = 'ninguno';
let mediaUrl = null;

if (videos.length > 0) {
  tipoMedia = 'video';
  mediaUrl = videos[0];
} else if (imagenes.length > 0) {
  tipoMedia = 'image';
  mediaUrl = imagenes[0];
}

return {
  json: {
    tieneMedia: tipoMedia !== 'ninguno',
    tipoMedia: tipoMedia,  // 'image', 'video', o 'ninguno'
    mediaUrl: mediaUrl,
    texto: textoLimpio,
    _guardia: guardia,
    _paso: paso
  }
};

// =============================================
// NORMALIZAR ENTRADA - Multi-Tenant Multi-Canal
// =============================================

const body = $input.first().json.body;
const messageType = body.message_type;
const event = body.event;

// --- 1. EXTRACCIÓN SEGURA DE DATOS (ANTES de decidir si saltamos) ---
const conversation = body.conversation || {};
const inbox = body.inbox || {};

// Intentamos obtener el inbox_id de todas las formas posibles y lo convertimos a entero
let raw_inbox_id = conversation.inbox_id || inbox.id || body.inbox_id || null;
const inbox_id = raw_inbox_id ? parseInt(raw_inbox_id) : null;

// --- 2. CHEQUEO DE SKIP (Salto) ---
if (event !== 'message_created' || messageType === 'outgoing' || messageType === 1) {
  // CORRECCIÓN: Devolvemos inbox_id aunque sea skip.
  return { 
    json: { 
      skip: true, 
      motivo: 'No es mensaje entrante',
      inbox_id: inbox_id || -1 
    } 
  };
}

// --- 3. RESTO DE LA LÓGICA (Solo para mensajes válidos) ---
const sender = body.sender || {};
const contact = conversation.meta?.sender || {};
const channel = conversation.channel || '';
const attachments = body.attachments || [];

const canal =
  channel.includes('Whatsapp') || channel.includes('Api') ? 'whatsapp' :
  channel.includes('FacebookPage') ? 'facebook' :
  channel.includes('Instagram') ? 'instagram' :
  channel.includes('WebWidget') ? 'web' : 'desconocido';

const senderId =
  contact.phone_number ||
  sender.phone_number ||
  conversation.meta?.sender?.phone_number ||
  sender.identifier ||
  contact.identifier ||
  String(sender.id || contact.id);

const senderName = sender.name || contact.name || 'Desconocido';
// CORRECCIÓN: Si es WebWidget, el teléfono suele ser null. Lo manejamos.
const senderPhone = contact.phone_number || sender.phone_number ||
                    conversation.meta?.sender?.phone_number || null;

const content = body.content || '';

const hasMedia = attachments.length > 0;
let mediaType = 'text';
let mediaUrl = null;
if (hasMedia) {
  mediaType = attachments[0].file_type || 'file';
  mediaUrl = attachments[0].data_url || null;
}

const customAttributes = conversation.custom_attributes || {};
const botActive = customAttributes.bot_status !== 'off';

return {
  json: {
    skip: false,
    canal: canal,
    inbox_id: inbox_id,
    sender_id: senderId,
    sender_name: senderName,
    sender_phone: senderPhone, // Puede ser null en WebWidget
    content: content,
    has_media: hasMedia,
    media_type: mediaType,
    media_url: mediaUrl,
    attachments: attachments,
    contact_id: sender.id || contact.id,
    conversation_id: conversation.id,
    account_id: body.account?.id,
    bot_active: botActive,
    created_at: body.created_at,
    _raw_body: body
  }
};

// =============================================
// RESOLVER TENANT - Combinar datos normalizados + canal
// =============================================

const norm = $('Normalizar Entrada').first().json;
const canal = $('Buscar Canal').first().json;

// Si no hay canal encontrado, paramos
if (!canal || !canal.business_id) {
  return { json: { skip: true, motivo: 'Tenant no encontrado para inbox_id: ' + norm.inbox_id } };
}

// Función auxiliar para limpiar solo números (elimina el + y cualquier otro caracter no numérico)
const limpiarTelefono = (num) => num ? String(num).replace(/\D/g, '') : num;

// Combinar toda la información del tenant
return {
  json: {
    // Datos del mensaje normalizado
    canal: norm.canal,
    inbox_id: norm.inbox_id,
    sender_id: limpiarTelefono(norm.sender_id),
    sender_name: norm.sender_name,
    sender_phone: limpiarTelefono(norm.sender_phone),
    content: norm.content,
    has_media: norm.has_media,
    media_type: norm.media_type,
    media_url: norm.media_url,
    attachments: norm.attachments,
    contact_id: norm.contact_id,
    conversation_id: norm.conversation_id,
    account_id: norm.account_id,
    bot_active: norm.bot_active,
    created_at: norm.created_at,
    _raw_body: norm._raw_body,

    // Datos del tenant
    business_id: canal.business_id,
    nombre_bot: canal.nombre_bot || 'Nilah',
    canal_activo: canal.activo
  }
};

// === Combinar Config Tenant ===
// Fusiona datos del webhook normalizado + datos del negocio desde Supabase
// + estado del bot por cliente (bot_pausado)

const canal = $('Resolver Tenant').first().json;
const negocio = $('Buscar Negocio').first().json;

// Leer bot_pausado del cliente (si existe el registro)
let botPausadoCliente = false;
let botPausadoHasta = null;
let botPausadoRazon = null;
try {
  const items = $('Buscar Bot Cliente').all();
  if (items && items.length > 0 && items[0].json && items[0].json.id) {
    const cli = items[0].json;
    botPausadoCliente = cli.bot_pausado === true;
    botPausadoHasta = cli.bot_pausado_hasta || null;
    botPausadoRazon = cli.bot_pausado_razon || null;
    // Si la fecha ya paso, tratamos como activo
    if (botPausadoCliente && botPausadoHasta) {
      const ahora = new Date();
      const hasta = new Date(botPausadoHasta);
      if (hasta <= ahora) {
        botPausadoCliente = false;
        botPausadoHasta = null;
        botPausadoRazon = null;
      }
    }
  }
} catch(e) {
  botPausadoCliente = false;
}

// Extraer recursos_saas (Feature Flags SaaS)
const recursosSaaS = negocio.recursos_saas || {
  plan_base: 'automatico',
  chatbot: { tipo: 'autonomo', activo: true },
  modulos: {},
  limites: { max_staff: 3 }
};

return [{
  json: {
    ...canal,
    business_id: negocio.id,
    nombre_bot: negocio.marca_identidad?.adn_json?.nombre_bot || recursosSaaS.chatbot?.nombre || negocio.bot_config?.nombre || 'Nilah',
    nombre_negocio: negocio.nombre,
    timezone: negocio.timezone || 'America/Lima',
    moneda: negocio.moneda || 'S/.',
    idioma: negocio.idioma || 'es-PE',
    bot_config: negocio.bot_config || {},
    recursos_saas: recursosSaaS,
    chatbot_tipo: recursosSaaS.chatbot?.tipo || 'autonomo',
    chatwoot_api_url: negocio.chatwoot_api_url || 'https://chat.koratflow.agency',
    chatwoot_api_token: negocio.chatwoot_api_token || '',
    chatwoot_account_id: negocio.chatwoot_account_id || canal.account_id,
    telefono_recepcionista: negocio.telefono_recepcionista,
    marca_identidad: negocio.marca_identidad || null,
    // --- NUEVO: Estado del bot por cliente ---
    bot_cliente_pausado: botPausadoCliente,
    bot_pausado_hasta: botPausadoHasta,
    bot_pausado_razon: botPausadoRazon
  }
}];

const output = $json.output || "";
const mockContext = $json._mockContext || null;

const problemas = [];

// ═══════════════════════════════════════════
// 1. RESPUESTA VACÍA
// ═══════════════════════════════════════════
if (output.trim().length === 0) {
  problemas.push("🔴 respuesta_vacia");
}

// ═══════════════════════════════════════════
// 2. RESPUESTA MUY CORTA
// ═══════════════════════════════════════════
if (output.trim().length > 0 && output.trim().length < 7) {
  problemas.push("🟡 respuesta_muy_corta");
}

// ═══════════════════════════════════════════
// 3. FUGA DE INFORMACIÓN TÉCNICA
// ═══════════════════════════════════════════
const patronesTecnicos = [
  /\berror\b/i,
  /exception/i,
  /undefined/i,
  /\bnull\b/i,
  /column.*not.*exist/i,
  /supabase/i,
  /postgresql/i,
  /ECONNREFUSED/i,
  /timeout/i,
  /\b500\b/,
  /\b403\b/,
  /\b404\b/,
  /stack.?trace/i,
  /node_modules/i,
  /ENOTFOUND/i,
  /ETIMEDOUT/i,
  /socket hang up/i,
  /fetch failed/i,
  /network error/i,
  /rate.?limit/i,
  /quota.?exceeded/i,
  /invalid.?api.?key/i,
  /authentication/i,
  /unauthorized/i,
  /CORS/i,
  /JSON\.parse/i,
  /syntax.?error/i,
  /cannot read propert/i,
  /is not defined/i,
  /is not a function/i,
  /unexpected token/i
];

for (const patron of patronesTecnicos) {
  if (patron.test(output)) {
    problemas.push("🔴 fuga_tecnica");
    break;
  }
}

// ═══════════════════════════════════════════
// 4. IDIOMA INCORRECTO
// ═══════════════════════════════════════════
const tieneEspanol = /[áéíóúñ¿¡]/i.test(output) ||
  /\b(hola|gracias|cita|servicio|salón|belleza|uñas|cabello|corte|color|turno|agenda|precio)\b/i.test(output);

const soloIngles = /\b(sorry|error|failed|unable|cannot|issue|problem|request|apologize)\b/i.test(output) && !tieneEspanol;

if (soloIngles && output.length > 20) {
  problemas.push("🟡 idioma_incorrecto");
}

// ═══════════════════════════════════════════
// 5. RESPUESTA REPETITIVA / LOOP
// ═══════════════════════════════════════════
const palabras = output.toLowerCase().split(/\s+/);
if (palabras.length > 10) {
  const frecuencia = {};
  for (const palabra of palabras) {
    if (palabra.length > 3) {
      frecuencia[palabra] = (frecuencia[palabra] || 0) + 1;
    }
  }
  const maxRepeticion = Math.max(...Object.values(frecuencia));
  if (maxRepeticion > palabras.length * 0.4) {
    problemas.push("🟡 respuesta_repetitiva");
  }
}

// ═══════════════════════════════════════════
// 6. ALUCINACIÓN DE CONTACTO FALSO
// ═══════════════════════════════════════════
const telefonoFalso = /\+?\d{1,3}[\s-]?\(?\d{2,4}\)?[\s-]?\d{3,4}[\s-]?\d{3,4}/.test(output);
const emailFalso = /[\w.-]+@[\w.-]+\.\w{2,}/.test(output);
const urlFalsa = /https?:\/\/(?!wa\.me)[\w.-]+/.test(output);

if (telefonoFalso || emailFalso || urlFalsa) {
  problemas.push("🟡 posible_alucinacion_contacto");
}

// ═══════════════════════════════════════════
// 7. RESPUESTA EXCESIVAMENTE LARGA
// ═══════════════════════════════════════════
if (output.length > 2000) {
  problemas.push("🟡 respuesta_muy_larga");
}

// ═══════════════════════════════════════════
// DECISIÓN
// ═══════════════════════════════════════════
const severidad = problemas.some(p => p.includes("🔴")) ? "CRITICO" : "WARNING";

if (problemas.length > 0) {
  return [{
    json: {
      output: "¡Ay, perdona! Me trabé un segundito 🙈 ¿Me podrías repetir eso? Quiero asegurarme de ayudarte bien 💛",
      _guardia: {
        problemas: problemas,
        severidad: severidad,
        outputOriginal: output.substring(0, 500),
        timestamp: new Date().toISOString()
      },
      _paso: "fallback",
      _mockContext: mockContext  // 👈 PASA EL CONTEXTO MOCK
    }
  }];
}

return [{
  json: {
    output: output,
    _guardia: { problemas: [], ok: true },
    _paso: "ok",
    _mockContext: mockContext
  }
}];

const guardia = $input.first().json._guardia;

if (!guardia || !guardia.problemas || guardia.problemas.length === 0) {
  return []; 
}

let business_id = null;
try {
  // Use optional chaining for safety
  const config = $('Combinar Config Tenant').first();
  if (config && config.json) {
    business_id = config.json.business_id;
  }
} catch (e) {}

let mensajeUsuario = "";
try {
  const norm = $('Normalizar Entrada').first();
  if (norm && norm.json) {
    mensajeUsuario = norm.json.content;
  }
} catch (e) {}

if (!mensajeUsuario) {
    try {
      const webhook = $('Webhook').first();
      if (webhook && webhook.json && webhook.json.body) {
           mensajeUsuario = webhook.json.body.content;
      }
    } catch(e2) {}
}

const outputOriginal = guardia.outputOriginal || "";
const errorMsg = Array.isArray(guardia.problemas) ? guardia.problemas.join(", ") : "Error desconocido";

return [{
  json: {
    business_id: business_id,
    workflow_name: "NilahIA_beauty_salon",
    nodo_fallido: "Guardia de Respuesta",
    mensaje_error: errorMsg,
    output_original: outputOriginal ? outputOriginal.substring(0, 500) : "",
    mensaje_usuario: mensajeUsuario ? mensajeUsuario.substring(0, 500) : "",
    execution_id: $execution.id
  }
}];

